/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's powerful type system with:
 * - Sealed traits for exhaustive pattern matching
 * - Case classes for immutable data structures
 * - Variance annotations for generic types
 * - Option/Either for safe error handling
 * - Type classes for ad-hoc polymorphism
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// ============================================================================
// Enums and Constants
// ============================================================================

/**
 * Token type enumeration using sealed trait pattern.
 */
sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }

  val values: Seq[TokenType] = Seq(String, Numeric, Temporal, Structured, Binary, Null)

  def fromString(s: String): Option[TokenType] = values.find(_.value == s)
}

// ============================================================================
// Protocol definitions (Type Classes)
// ============================================================================

/**
 * Type class for objects that can be converted to a token string.
 */
trait Tokenizable[A] {
  def toToken(value: A): String
}

object Tokenizable {
  def apply[A](implicit ev: Tokenizable[A]): Tokenizable[A] = ev

  implicit val stringTokenizable: Tokenizable[String] = (value: String) => value
  implicit val intTokenizable: Tokenizable[Int] = (value: Int) => value.toString
  implicit val longTokenizable: Tokenizable[Long] = (value: Long) => value.toString
  implicit val doubleTokenizable: Tokenizable[Double] = (value: Double) => value.toString
  implicit val bigDecimalTokenizable: Tokenizable[BigDecimal] = (value: BigDecimal) => value.toString
}

/**
 * Type class for objects with a length.
 */
trait HasLength[A] {
  def length(value: A): Int
}

object HasLength {
  implicit val stringHasLength: HasLength[String] = (value: String) => value.length
  implicit def seqHasLength[A]: HasLength[Seq[A]] = (value: Seq[A]) => value.length
  implicit def arrayHasLength[A]: HasLength[Array[A]] = (value: Array[A]) => value.length
}

/**
 * Type class for processors that consume tokens.
 */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

object Token {
  val Null: Token = Token("NULL", TokenType.Null)
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
class MutableTokenBatch {
  private val _tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty
  private var _processed: Boolean = false

  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def isProcessed: Boolean = _processed
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
class TokenContainer[+A](items: Seq[A]) {
  private val _items: Vector[A] = items.toVector

  def getAll: Vector[A] = _items

  def mapTokens[B](func: A => B): Vector[B] = _items.map(func)
}

/**
 * Contravariant sink - can accept supertypes.
 */
class TokenSink[-A] {
  private val _received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: A): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 */
class BivariantHandler[A](private var _value: A) {
  def get: A = _value

  def set(value: A): Unit = {
    _value = value
  }

  def transform(func: A => A): A = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[A] {
  /**
   * Convert value to token.
   */
  def tokenize(value: A): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/**
 * Input type for StringTokenizer - either String or Array[Byte].
 */
sealed trait StringOrBytes {
  def asString(encoding: String): String
}

object StringOrBytes {
  case class Str(value: String) extends StringOrBytes {
    def asString(encoding: String): String = value
  }

  case class Bytes(value: Array[Byte]) extends StringOrBytes {
    def asString(encoding: String): String = new String(value, encoding)
  }

  implicit def fromString(s: String): StringOrBytes = Str(s)
  implicit def fromBytes(b: Array[Byte]): StringOrBytes = Bytes(b)
}

/**
 * Tokenizer for string and bytes types.
 */
class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[StringOrBytes] {

  override def tokenize(value: StringOrBytes): Token = {
    val strValue = value.asString(encoding)
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.String)
  }
}

/**
 * Input type for NumericTokenizer.
 */
sealed trait NumericValue {
  def format(precision: Int): String
  def typeName: String
}

object NumericValue {
  case class IntValue(value: Int) extends NumericValue {
    def format(precision: Int): String = value.toString
    def typeName: String = "Int"
  }

  case class LongValue(value: Long) extends NumericValue {
    def format(precision: Int): String = value.toString
    def typeName: String = "Long"
  }

  case class FloatValue(value: Float) extends NumericValue {
    def format(precision: Int): String = s"%.${precision}f".format(value)
    def typeName: String = "Float"
  }

  case class DoubleValue(value: Double) extends NumericValue {
    def format(precision: Int): String = s"%.${precision}f".format(value)
    def typeName: String = "Double"
  }

  case class DecimalValue(value: BigDecimal) extends NumericValue {
    def format(precision: Int): String = s"%.${precision}f".format(value)
    def typeName: String = "BigDecimal"
  }

  implicit def fromInt(v: Int): NumericValue = IntValue(v)
  implicit def fromLong(v: Long): NumericValue = LongValue(v)
  implicit def fromFloat(v: Float): NumericValue = FloatValue(v)
  implicit def fromDouble(v: Double): NumericValue = DoubleValue(v)
  implicit def fromBigDecimal(v: BigDecimal): NumericValue = DecimalValue(v)
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  override def tokenize(value: NumericValue): Token = {
    val strValue = value.format(precision)
    Token(strValue, TokenType.Numeric, Map("original_type" -> value.typeName))
  }
}

/**
 * Input type for TemporalTokenizer.
 */
sealed trait TemporalValue {
  def format(formatter: DateTimeFormatter): String
  def isDateTime: Boolean
}

object TemporalValue {
  case class DateTime(value: LocalDateTime) extends TemporalValue {
    def format(formatter: DateTimeFormatter): String = value.format(formatter)
    def isDateTime: Boolean = true
  }

  case class Date(value: LocalDate) extends TemporalValue {
    def format(formatter: DateTimeFormatter): String = value.format(formatter)
    def isDateTime: Boolean = false
  }

  implicit def fromDateTime(dt: LocalDateTime): TemporalValue = DateTime(dt)
  implicit def fromDate(d: LocalDate): TemporalValue = Date(d)
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[TemporalValue] {

  private val isoFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: TemporalValue): Token = {
    val formatter = formatStr match {
      case Some(fmt) => DateTimeFormatter.ofPattern(fmt)
      case None if value.isDateTime => isoFormat
      case None => dateFormat
    }
    Token(value.format(formatter), TokenType.Temporal)
  }
}

object TemporalTokenizer {
  val IsoFormat: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat: String = "yyyy-MM-dd"
}

// ============================================================================
// Advanced: Union Types via Sealed Trait
// ============================================================================

/**
 * Universal input type that can hold any tokenizable value.
 */
sealed trait UniversalInput

object UniversalInput {
  case class StringInput(value: String) extends UniversalInput
  case class BytesInput(value: Array[Byte]) extends UniversalInput
  case class IntInput(value: Int) extends UniversalInput
  case class LongInput(value: Long) extends UniversalInput
  case class FloatInput(value: Float) extends UniversalInput
  case class DoubleInput(value: Double) extends UniversalInput
  case class DecimalInput(value: BigDecimal) extends UniversalInput
  case class DateTimeInput(value: LocalDateTime) extends UniversalInput
  case class DateInput(value: LocalDate) extends UniversalInput
  case class TokenizableInput[A](value: A)(implicit ev: Tokenizable[A]) extends UniversalInput {
    def toToken: String = ev.toToken(value)
  }
  case object NullInput extends UniversalInput
  case class FallbackInput(value: Any) extends UniversalInput

  implicit def fromString(s: String): UniversalInput = StringInput(s)
  implicit def fromBytes(b: Array[Byte]): UniversalInput = BytesInput(b)
  implicit def fromInt(i: Int): UniversalInput = IntInput(i)
  implicit def fromLong(l: Long): UniversalInput = LongInput(l)
  implicit def fromFloat(f: Float): UniversalInput = FloatInput(f)
  implicit def fromDouble(d: Double): UniversalInput = DoubleInput(d)
  implicit def fromBigDecimal(bd: BigDecimal): UniversalInput = DecimalInput(bd)
  implicit def fromDateTime(dt: LocalDateTime): UniversalInput = DateTimeInput(dt)
  implicit def fromDate(d: LocalDate): UniversalInput = DateInput(d)
}

/**
 * Tokenizer that handles multiple types with pattern matching dispatch.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: UniversalInput): Token = value match {
    case UniversalInput.NullInput =>
      Token.Null

    case UniversalInput.TokenizableInput(v) =>
      Token(v.asInstanceOf[{ def toToken: String }].toToken, TokenType.Structured)

    case UniversalInput.StringInput(s) =>
      stringTokenizer.tokenize(StringOrBytes.Str(s))

    case UniversalInput.BytesInput(b) =>
      stringTokenizer.tokenize(StringOrBytes.Bytes(b))

    case UniversalInput.IntInput(i) =>
      numericTokenizer.tokenize(NumericValue.IntValue(i))

    case UniversalInput.LongInput(l) =>
      numericTokenizer.tokenize(NumericValue.LongValue(l))

    case UniversalInput.FloatInput(f) =>
      numericTokenizer.tokenize(NumericValue.FloatValue(f))

    case UniversalInput.DoubleInput(d) =>
      numericTokenizer.tokenize(NumericValue.DoubleValue(d))

    case UniversalInput.DecimalInput(bd) =>
      numericTokenizer.tokenize(NumericValue.DecimalValue(bd))

    case UniversalInput.DateTimeInput(dt) =>
      temporalTokenizer.tokenize(TemporalValue.DateTime(dt))

    case UniversalInput.DateInput(d) =>
      temporalTokenizer.tokenize(TemporalValue.Date(d))

    case UniversalInput.FallbackInput(v) =>
      Token(v.toString, TokenType.String, Map("fallback" -> true))
  }

  /**
   * Convenience method for tokenizing any value.
   */
  def tokenizeAny(value: Any): Token = {
    val input: UniversalInput = value match {
      case null => UniversalInput.NullInput
      case s: String => UniversalInput.StringInput(s)
      case b: Array[Byte] => UniversalInput.BytesInput(b)
      case i: Int => UniversalInput.IntInput(i)
      case l: Long => UniversalInput.LongInput(l)
      case f: Float => UniversalInput.FloatInput(f)
      case d: Double => UniversalInput.DoubleInput(d)
      case bd: BigDecimal => UniversalInput.DecimalInput(bd)
      case jbd: java.math.BigDecimal => UniversalInput.DecimalInput(BigDecimal(jbd))
      case dt: LocalDateTime => UniversalInput.DateTimeInput(dt)
      case d: LocalDate => UniversalInput.DateInput(d)
      case other => UniversalInput.FallbackInput(other)
    }
    tokenize(input)
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 */
class TokenRegistry[A] {
  private val registry: mutable.Map[String, TokenContainer[A]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[A => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[A]): Unit = {
    registry(key) = container
  }

  def addHandler(handler: A => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(h => h(item))
            .find(_.isDefined)
            .flatten
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation (Functor/Monad)
// ============================================================================

/**
 * Functor for tokens.
 */
class TokenFunctor[A](protected val _value: A) {
  def map[B](func: A => B): TokenFunctor[B] =
    new TokenFunctor(func(_value))

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] =
    func(_value)

  def getOrElse(default: => A): A =
    if (_value != null) _value else default

  def get: A = _value
}

/**
 * Extended monad operations.
 */
class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(this._value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Recursive JSON value type.
 */
sealed trait JsonValue

object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: BigDecimal) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  // Conversion helpers
  implicit def fromString(s: String): JsonValue = JsonString(s)
  implicit def fromInt(i: Int): JsonValue = JsonNumber(BigDecimal(i))
  implicit def fromDouble(d: Double): JsonValue = JsonNumber(BigDecimal(d))
  implicit def fromBoolean(b: Boolean): JsonValue = JsonBoolean(b)
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) toJsonPretty(value, 0) else toJson(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    extractPath(value, parts).map(tokenize)
  }

  private def extractPath(value: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(value)
    case head :: tail =>
      value match {
        case JsonValue.JsonObject(fields) =>
          fields.get(head).flatMap(v => extractPath(v, tail))
        case JsonValue.JsonArray(values) =>
          Try(head.toInt).toOption
            .filter(idx => idx >= 0 && idx < values.length)
            .flatMap(idx => extractPath(values(idx), tail))
        case _ => None
      }
  }

  private def toJson(value: JsonValue): String = value match {
    case JsonValue.JsonString(s) => s""""${escapeJson(s)}""""
    case JsonValue.JsonNumber(n) => n.toString
    case JsonValue.JsonBoolean(b) => b.toString
    case JsonValue.JsonNull => "null"
    case JsonValue.JsonArray(values) =>
      values.map(toJson).mkString("[", ",", "]")
    case JsonValue.JsonObject(fields) =>
      fields.map { case (k, v) => s""""${escapeJson(k)}":${toJson(v)}""" }.mkString("{", ",", "}")
  }

  private def toJsonPretty(value: JsonValue, indent: Int): String = {
    val spaces = "  " * indent
    val innerSpaces = "  " * (indent + 1)

    value match {
      case JsonValue.JsonString(s) => s""""${escapeJson(s)}""""
      case JsonValue.JsonNumber(n) => n.toString
      case JsonValue.JsonBoolean(b) => b.toString
      case JsonValue.JsonNull => "null"
      case JsonValue.JsonArray(values) if values.isEmpty => "[]"
      case JsonValue.JsonArray(values) =>
        values.map(v => innerSpaces + toJsonPretty(v, indent + 1)).mkString("[\n", ",\n", s"\n$spaces]")
      case JsonValue.JsonObject(fields) if fields.isEmpty => "{}"
      case JsonValue.JsonObject(fields) =>
        fields.map { case (k, v) =>
          s"""$innerSpaces"${escapeJson(k)}": ${toJsonPretty(v, indent + 1)}"""
        }.mkString("{\n", ",\n", s"\n$spaces}")
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {

  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0

    text.split("\\s+").filter(_.nonEmpty).foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 */
class TokenizerBuilder[A] private (
  normalizers: List[String => String],
  validators: List[A => Boolean],
  metadata: Map[String, Any]
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizer :: normalizers, validators, metadata)

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validator :: validators, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators, metadata ++ entries.toMap)

  /**
   * Build the final tokenizer function.
   */
  def build(): A => Token = { value =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize (apply in reverse order since we prepend to list)
    normalizers.reverse.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.String, metadata)
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] = new TokenizerBuilder[A](Nil, Nil, Map.empty)
}

